import{_ as l,c as i,o as t,ak as n}from"./chunks/framework.CtX3_w5e.js";const P=JSON.parse('{"title":"Sentinel","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"Sentinel","hugoSource":"computer-science/distributed-system/Sentinel.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/distributed-system/2026-11-17-Sentinel.md","filePath":"computer-science/distributed-system/2026-11-17-Sentinel.md","lastUpdated":1794887319000}'),a={name:"computer-science/distributed-system/2026-11-17-Sentinel.md"};function r(o,e,s,S,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="sentinel" tabindex="-1">Sentinel <a class="header-anchor" href="#sentinel" aria-label="Permalink to “Sentinel”">​</a></h1><h2 id="性能压测" tabindex="-1">性能压测 <a class="header-anchor" href="#性能压测" aria-label="Permalink to “性能压测”">​</a></h2><ul><li>“引入Sentinel带来的性能损耗非常小，只有在业务单机量级超过25万QPS的时候才会有一些显著的影响（5%～10%左右），单机QPS不太大的时候损耗几乎可以忽略不计。”这是Sentinel官方文档中的一句话，本节将通过基准测试验证这句话。</li></ul><h2 id="spi在sentinel中的应用" tabindex="-1">SPI在Sentinel中的应用 <a class="header-anchor" href="#spi在sentinel中的应用" aria-label="Permalink to “SPI在Sentinel中的应用”">​</a></h2><ul><li>SPI机制在阿里巴巴集团开源的项目中被广泛使用，如Dubbo，RocketMQ与Sentinel都使用了SPI机制</li><li>除了Dubbo外，RocketMQ与Sentinel使用的都是Java提供的SPI机制</li><li>Dubbo使用的是自实现的一套SPI——Dubbo SPI，与Java SPI的配置方式不同，Dubbo SPI使用Key-Value方式配置，目的是实现自适应扩展机制</li><li><strong>Java SPI实现原理与适用场景</strong><ul><li>SPI（Service Provider Interface，服务提供者接口）是一种服务发现机制，是Java的一个内置标准，可以保障不同的开发者实现某个特定的服务</li><li>SPI的本质是将接口实现类的全限定名配置在文件中，由服务加载器读取配置文件、加载实现类并创建实例。使用SPI机制能够实现运行时从配置文件中读取接口的实现类并创建实例</li><li>ServiceLoader.load()</li><li>SPI机制的适用场景 <ul><li>适合适用<strong>策略模式</strong>、<strong>责任链模式</strong>的场景都可以使用SPI机制</li></ul></li></ul></li><li><strong>Java SPI在Sentinel中的应用</strong><ul><li>我们可以直接替换Sentinel提供的默认SlotChainBuilder，使用自定义的SlotChainBuilder为资源构造自己的ProcessorSlotChain，以实现修改ProcessorSlot排列顺序、增加或移除ProcessorSlot的功能</li></ul></li></ul><h2 id="责任链模式在sentinel中的应用" tabindex="-1">责任链模式在Sentinel中的应用 <a class="header-anchor" href="#责任链模式在sentinel中的应用" aria-label="Permalink to “责任链模式在Sentinel中的应用”">​</a></h2><ul><li>我们将Sentinel提供的所有ProcessorSlot分为两类 <ul><li>一类是负责完成资源指标数据统计的ProcessorSlot</li><li>一类是实现限流、熔断等流量控制功能的ProcessorSlot</li></ul></li><li>Sentinel使用责任链模式将注册的所有ProcessorSlot按照一定的顺序串成一个单向链表</li><li>实现资源指标数据统计的ProcessorSlot必须在实现流量控制功能的ProcessorSlot的前面，原因很简单，限流、熔断降级等都需要依赖资源的实时指标数据做判断</li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="https://book.douban.com/subject/35777055/" target="_blank" rel="noreferrer">实战Alibaba Sentinel：深度解析微服务高并发流量治理</a></li></ul>',9)])])}const h=l(a,[["render",r]]);export{P as __pageData,h as default};
